-- Migration: Year 2 - Sexual & Forensic Pathology MCQs Part 3 (76-115)
-- Date: 2026-04-24

BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Sexual & Forensic Pathology', 'sexual-forensic-pathology', 3, 2, 62)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES

    -- SYPHILIS (76-90)
    (v_topic_id, 'Primary syphilis is characterized by a "chancre." What are the typical features of a syphilitic chancre?', '["Painful, soft ulcer with ragged edges", "Painless, indurated (hard) ulcer with a clean base and painless regional lymphadenopathy", "Multiple small vesicles on an erythematous base", "Foul-smelling discharge with no ulcer"]', 1, 'Primary syphilis (Treponema pallidum) presents as a single, painless, indurated ulcer (chancre) at the site of inoculation. It is highly infectious. It heals spontaneously in 3-6 weeks even without treatment, but the bacteria continue to disseminate.'),
    (v_topic_id, 'Secondary syphilis classically presents with which clinical finding?', '["Aortic aneurysm", "Widespread maculopapular rash involving the palms and soles, and condylomata lata", "Tabes dorsalis", "A solitary hard chancre"]', 1, 'Secondary syphilis occurs weeks to months after the chancre. It is a systemic stage characterized by a generalized maculopapular rash (classically involving palms and soles), generalized lymphadenopathy, and condylomata lata (smooth, moist, flat-topped papules in intertriginous areas). All lesions are highly infectious.'),
    (v_topic_id, 'Tertiary syphilis can involve the cardiovascular system. What is the classic manifestation?', '["Mitral valve prolapse", "Aortitis involving the vasa vasorum of the ascending aorta, leading to aneurysm and aortic regurgitation", "Myocarditis", "Coronary artery disease"]', 1, 'Tertiary syphilis causes "endarteritis obliterans" of the vasa vasorum. This weakens the adventitia of the ascending aorta, leading to aneurysmal dilation and often involving the aortic valve ring (causing aortic regurgitation). A ''tree-bark'' appearance of the aortic intima is characteristic.'),
    (v_topic_id, 'Neurosyphilis in the tertiary stage can cause Tabes Dorsalis. What is the pathological basis?', '["Destruction of the anterior horn cells", "Degeneration of the dorsal columns and dorsal roots of the spinal cord, leading to loss of proprioception and ataxia", "Demyelination of the lateral corticospinal tracts", "Basal ganglia infarction"]', 1, 'Tabes dorsalis is caused by Treponema pallidum attacking the dorsal columns and dorsal roots. Patients lose vibration sense and proprioception, leading to a wide-based gait (sensory ataxia) and positive Romberg sign. Associated with "Argyll Robertson pupils" (accommodate but do not react to light).'),
    (v_topic_id, 'What are "gummas" in the context of tertiary syphilis?', '["Purulent abscesses", "Chronic, granulomatous lesions with central necrosis that can occur in skin, bone, or internal organs", "Small vesicles", "Malignant transformations"]', 1, 'Gummas are rubbery, necrotic, granulomatous lesions found in tertiary syphilis. They result from a delayed hypersensitivity response to the spirochete. They can be destructive to bone or skin.'),
    (v_topic_id, 'Congenital syphilis can present with "Hutchinson triad." What does this include?', '["Fever, rash, and jaundice", "Hutchinson teeth (notched incisors), interstitial keratitis, and sensorineural deafness (CN VIII)", "Saddle nose, saber shins, and rhagades", "Cataracts, PDA, and microcephaly"]', 1, 'Hutchinson triad: 1. Hutchinson teeth (blunted, notched incisors); 2. Interstitial keratitis (clouding of cornea); 3. VIIIth nerve deafness. Other signs include ''saddle nose'' and ''saber shins'' (bowing of the tibia).'),
    (v_topic_id, 'Which test is a "non-treponemal" screening test for syphilis?', '["FTA-ABS", "VDRL or RPR (detects antibodies against cardiolipin-lecithin-cholesterol antigen)", "TP-PA", "MHA-TP"]', 1, 'VDRL and RPR are non-treponemal tests. They are sensitive for screening but not specific (can be positive in SLE, viral infections, pregnancy). They measure antibodies against cardiolipin, a component of T. pallidum and mitochondrial membranes. Treponemal tests (FTA-ABS, TP-PA) are used for confirmation.'),
    (v_topic_id, 'The Jarisch-Herxheimer reaction is a complication of syphilis treatment. What is the cause?', '["Allergic reaction to Penicillin", "Acute inflammatory response to the release of endotoxin-like substances from dying spirochetes after starting antibiotics", "Immediate reinfection", "Drug-induced liver injury"]', 1, 'Jarisch-Herxheimer reaction: occurs within hours of starting treatment (usually Penicillin). Symptoms include fever, chills, headache, and myalgias. It is NOT an allergy; it is a response to massive bacterial lysis.'),

    -- GONORRHEA & CHLAMYDIA (91-100)
    (v_topic_id, 'Neisseria gonorrhoeae is a Gram-negative diplococcus. What is the typical presentation in men?', '["Painless ulcer", "Acute urethritis with purulent discharge and dysuria", "Chronic scrotal swelling", "No symptoms at all"]', 1, 'Gonorrhea in men typically causes acute, symptomatic urethritis with a thick, yellowish-green purulent discharge. Complications include epididymitis and proctitis.'),
    (v_topic_id, 'What is the most common cause of non-gonococcal urethritis (NGU)?', '["Mycoplasma genitalium", "Chlamydia trachomatis (D-K serotypes)", "Trichomonas vaginalis", "Ureaplasma urealyticum"]', 1, 'Chlamydia trachomatis (serotypes D-K) is the most common cause of NGU. It often presents with a more mucoid (clearer) discharge than gonorrhea and is frequently asymptomatic, facilitating transmission.'),
    (v_topic_id, 'Disseminated Gonococcal Infection (DGI) classically presents with?', '["Aortic aneurysm", "Triad of tenosynovitis, dermatitis (pustular lesions), and polyarthralgia; or purulent monoarthritis", "Chronic meningitis", "Saddle nose"]', 1, 'DGI occurs when N. gonorrhoeae enters the bloodstream. It presents either as a syndrome of tenosynovitis, skin lesions (petechial or pustular), and migratory polyarthralgia, or as a localized septic arthritis (usually of the knee, wrist, or ankle).'),
    (v_topic_id, 'Pelvic Inflammatory Disease (PID) is a serious complication of STIs in women. Which two organisms are the most frequent causes?', '["Streptococcus and Staphylococcus", "Neisseria gonorrhoeae and Chlamydia trachomatis", "Escherichia coli and Proteus", "HSV and HPV"]', 1, 'PID is most often caused by ascending infection of N. gonorrhoeae or C. trachomatis. It can lead to salpingitis, tubo-ovarian abscess, and long-term sequelae like ectopic pregnancy and infertility due to tubal scarring.'),
    (v_topic_id, 'Fitz-Hugh-Curtis syndrome is a complication of PID. What does it involve?', '["Brain abscess", "Perihepatitis with ''violin-string'' adhesions between the liver capsule and the parietal peritoneum", "Splenic infarction", "Myocarditis"]', 1, 'Fitz-Hugh-Curtis syndrome is an inflammation of the liver capsule (perihepatitis) associated with PID. On laparoscopy, classic ''violin-string'' fibrous adhesions are seen.'),
    (v_topic_id, 'Lymphogranuloma venereum (LGV) is caused by which serotypes of Chlamydia trachomatis?', '["Serotypes A, B, C", "Serotypes L1, L2, L3", "Serotypes D-K", "None of the above"]', 1, 'LGV is caused by C. trachomatis serotypes L1-L3. It presents with a small, painless primary ulcer followed by painful, fluctuant inguinal lymphadenopathy ("buboes"). Chronic infection can lead to proctocolitis and lymphatic obstruction.'),
    (v_topic_id, 'Neonatal conjunctivitis (ophthalmia neonatorum) caused by Chlamydia usually appears when?', '["Within 24 hours of birth", "5-14 days after birth", "3 weeks after birth", "At birth"]', 1, 'Chlamydial conjunctivitis typically appears 5-14 days after birth. In contrast, Gonococcal conjunctivitis is more acute and severe, appearing 2-5 days after birth. Chemical conjunctivitis (from silver nitrate) appears within 24 hours.'),

    -- OTHER STIs: CHANCROID, HSV, TRICHOMONAS (101-115)
    (v_topic_id, 'Chancroid is caused by Haemophilus ducreyi. How does it differ from a syphilitic chancre?', '["It is painless", "It is a painful, ''soft'' ulcer with ragged, undermined edges and painful inguinal lymphadenopathy (buboes)", "It has a clean base", "It is always single"]', 1, 'Chancroid ("You do cry" with Ducreyi because it is painful) presents as one or more painful ulcers with a grey/yellow exudative base and shaggy edges. The associated inguinal lymphadenopathy is also painful and can suppurate (buboes).'),
    (v_topic_id, 'Genital herpes is most commonly caused by HSV-2. What is the classic appearance of the primary infection?', '["A single hard ulcer", "Multiple painful, small vesicles on an erythematous base that rupture to form shallow ulcers", "A cauliflower-like growth", "A diffuse rash"]', 1, 'Primary HSV infection presents as groups of small, painful, fluid-filled vesicles. When they rupture, they leave painful shallow ulcers. The virus then remains latent in the sacral nerve ganglia.'),
    (v_topic_id, 'What is a "Tzanck smear" used for?', '["To diagnose syphilis", "To identify multinucleated giant cells characteristic of Herpes Simplex Virus (HSV) or Varicella-Zoster Virus (VZV)", "To culture gonorrhea", "To detect Chlamydia elementary bodies"]', 1, 'A Tzanck smear is a rapid bedside test where a scrap of an ulcer base is stained. The presence of multinucleated giant cells suggests HSV or VZV. Modern diagnosis usually relies on PCR or viral culture.'),
    (v_topic_id, 'Granuloma inguinale (donovanosis) is caused by Klebsiella granulomatis. What is seen on tissue biopsy?', '["Atypical lymphocytes", "Donovan bodies (safety-pin shaped organisms inside macrophages)", "Reed-Sternberg cells", "Koilocytes"]', 1, 'Donovanosis presents as painless, beefy-red, highly vascular ulcers that bleed easily. Histology shows "Donovan bodies" — intracellular Gram-negative bacilli within macrophages.'),
    (v_topic_id, 'Trichomoniasis is caused by a protozoan. What is the characteristic finding on pelvic exam in women?', '["Thin, white, fishy-smelling discharge", "Thick, ''cottage-cheese'' discharge", "Malodorous, thin, frothy, yellow-green discharge and a ''strawberry cervix'' (punctate hemorrhages)", "No discharge at all"]', 2, 'Trichomonas vaginalis causes a profuse, malodorous discharge and intense vaginal irritation. The ''strawberry cervix'' (colpitis macularis) is a classic but not universal finding. Wet mount shows motile, pear-shaped flagellated protozoa.'),
    (v_topic_id, 'Bacterial vaginosis (BV) is NOT strictly an STI but is associated with sexual activity. What is the pathognomonic finding on wet mount?', '["Motile protozoa", "Clue cells (vaginal epithelial cells covered in Gardnerella vaginalis bacteria, giving them a fuzzy appearance)", "Pseudohyphae", "Giant cells"]', 1, 'BV results from a shift in vaginal flora (loss of Lactobacilli, overgrowth of Anaerobes like Gardnerella). Amsel criteria: 1. Homogeneous white discharge; 2. Vaginal pH > 4.5; 3. Positive whiff test (fishy odor with KOH); 4. Clue cells on wet mount.'),
    (v_topic_id, 'Vulvovaginal Candidiasis (yeast infection) typically presents with?', '["Frothy green discharge", "Thick, white, ''cottage-cheese'' like discharge with intense pruritus and normal vaginal pH", "Fishy odor", "Painless ulcers"]', 1, 'Candidiasis is caused by Candida albicans overgrowth. It causes itching, burning, and a characteristic thick discharge. Unlike BV and Trichomonas, the vaginal pH is typically NORMAL (<4.5). Wet mount shows budding yeast or pseudohyphae.'),
    (v_topic_id, 'HPV types 6 and 11 cause Condyloma Acuminatum. What is the classic histological finding in HPV-infected cells?', '["Donovan bodies", "Koilocytes (cells with wrinkled, raisin-like nuclei and a large perinuclear clear halo)", "Auer rods", "Call-Exner bodies"]', 1, 'Koilocytes are the hallmark of HPV infection. They are squamous epithelial cells that have undergone structural changes due to the virus. They are seen in both benign warts and in precancerous lesions (CIN).')

    ON CONFLICT DO NOTHING;

END $$;

COMMIT;
